// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // _feeRate is the fuzzed input, ranges over 0..65535
        // We allow any value except the one that would block initialization for completely different reasons
        // The only precondition is that initialization itself does not revert due to other checks.
        // Actually, the only revert that can block us is AlreadyInitialized, which we avoid by deploying a fresh C.
        // The failing check was the FeeRateTooHigh, now removed.

        // For reproducibility, we ensure that C is fresh each time by deploying in setUp, but we need a clean state.
        // Since testFuzz_property gets a new c for each fuzz run, we can just call initialize.
        // However, we must provide valid-looking arguments to satisfy other checks (if any).
        // The initialize function checks if (initialized) revert AlreadyInitialized, and nothing else before the fee rate check.
        // So we can call it with any args.

        address _baseToken = address(0);
        address _nft = address(0x1);
        uint128 _virtualBaseTokenReserves = 1;
        uint128 _virtualNftReserves = 1;
        uint56 _changeFee = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        // We will try to initialize and then read back the feeRate
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            // Succeeded, now check the stored feeRate
            uint256 storedFeeRate = c.feeRate();
            assertTrue(storedFeeRate <= 5000);
        } catch {
            // If it reverted, it's fine (maybe other reasons). The test only cares about the case when it succeeds.
            // In the reference version, it reverts for >5000, so we never reach the assertion in that case.
            // In the buggy version, it succeeds for >5000 and we assert.
            // So if it succeeded, we enforce the property.
            // This is a valid universal property: for any successful initialization, feeRate <= 5000.
            // The bug violates it because there exist successful initializations with feeRate > 5000.
        }
    }
}
